  // Auch der italienische Raum zieht zusätzlich aus dem gemeinsamen Zusatzspeicher —
  // dadurch lassen sich seine Kategorien genauso auf jedem Niveau auffüllen wie die
  // deutschen, ohne ein zweites Datenformat zu pflegen.
  function itBank(id) {
    return (IT_BANKEN[id] || []).map(([prompt, options, correctIdx, explain, level]) => ({
      prompt, options, correct: [correctIdx], explain, level,
    })).concat(zusatzBank(id));
  }

  /* =========================================================================
     Umschalter zwischen Lernraum Deutsch und Lernraum Italienisch
     -------------------------------------------------------------------------
     Der Rest der App fragt ab jetzt nicht mehr direkt CATEGORIES oder
     GRAMMATIK ab, sondern activeCategories() bzw. activeGrammatik(). So
     genügt ein einziger Schalter, um die gesamte Oberfläche umzustellen,
     ohne jede einzelne Stelle anzufassen.
     ========================================================================= */
  let lernraum = "de";
  function setLernraum(r) { lernraum = (r === "it") ? "it" : "de"; }
  function getLernraum() { return lernraum; }
  function activeCategories() { return lernraum === "it" ? IT_KATEGORIEN : CATEGORIES; }
  function activeGetCategory(id) { return activeCategories().find((c) => c.id === id); }
  function activeGrammatik() { return lernraum === "it" ? IT_GRAMMATIK : GRAMMATIK; }
  function activeWoerter() { return lernraum === "it" ? IT_WOERTER : null; }
  function activeHistoryForToday(monthDay) {
    if (lernraum === "it") return IT_GESCHICHTE[monthDay] || null;
    return germanHistoryForToday(monthDay);
  }
  function activeHistoryEntries() {
    if (lernraum !== "it") return getAllHistoryEntries();
    return Object.entries(IT_GESCHICHTE).map(([monthDay, e]) => ({ monthDay, ...e })).sort((a, b) => a.monthDay.localeCompare(b.monthDay));
  }
  function activeHistoryTitle() {
    return lernraum === "it" ? "📜 C'era una volta in Italia …" : "📜 Es war einmal in Deutschland …";
  }

