  function zusatzBank(id) {
    return Core.shuffle(ZUSATZ_FRAGEN[id] || []).map(([prompt, correct, wrongs, explain, level, uebersetzung]) => {
      const opts = Core.shuffle([correct, ...wrongs]);
      // uebersetzung (optional, 6. Feld): die deutsche Entsprechung des VOLLSTÄNDIGEN Satzes
      // mit eingesetzter Lösung. Wird im Italienisch-Raum auf Wunsch eingeblendet, damit man
      // nicht raten muss, was der Beispielsatz überhaupt bedeutet.
      return { prompt, options: opts, correct: [opts.indexOf(correct)], explain, level, uebersetzung: uebersetzung || "" };
    });
  }
  // Hängt die Zusatzfragen einer Kategorie an ihren bestehenden Bestand an,
  // ohne dass die ursprüngliche Bank-Funktion angefasst werden muss.
  function mitZusatz(id, fn) {
    return (...args) => fn(...args).concat(zusatzBank(id));
  }

